"""symbols.txt and splits.txt, decomp-toolkit's layout formats (generated by tools/layout.py, read by the split).

symbols.txt, one symbol a line:

    _mainCRTStartup = .text:0x00401000; // type:function size:0x68 scope:global

splits.txt, the sections and then each unit (translation unit) in link order with its range of each section:

    Sections:
        .text       type:code align:16
    src/runtime/maincrt.c:
        .text       start:0x00401000 end:0x00401070
        .exc        start:0x00581000 end:0x00581008 rename:.exc$BBB

Both readers keep every option in order and both writers produce the files' exact text, so read-then-write is the
identity (every version's files round-trip byte for byte).
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

from .project import Error, relative


class FormatError(Error):
    pass


def _options(text: str, where: str) -> list[tuple[str, str]]:
    out = []
    for token in text.split():
        key, colon, value = token.partition(":")
        if not colon or not key:
            raise FormatError(f"{where}: option {token!r} is not key:value")
        out.append((key, value))
    return out


def _format_options(options: list[tuple[str, str]]) -> str:
    return " ".join(f"{k}:{v}" for k, v in options)


# ------------------------------------------------------------------------------------------------------ symbols.txt


@dataclass
class Symbol:
    name: str
    section: str
    address: int
    options: list[tuple[str, str]] = field(default_factory=list)

    def option(self, key: str, default=None):
        return next((v for k, v in self.options if k == key), default)

    @property
    def size(self) -> int | None:
        size = self.option("size")
        return int(size, 0) if size is not None else None

    @property
    def kind(self) -> str | None:
        """type: function, object, label ..."""
        return self.option("type")

    @property
    def scope(self) -> str | None:
        return self.option("scope")

    def line(self) -> str:
        text = f"{self.name} = {self.section}:0x{self.address:08X};"
        if self.options:
            text += " // " + _format_options(self.options)
        return text


_SYMBOL = re.compile(r"(\S+) = ([^:\s]+):0x([0-9A-Fa-f]+);(?: // (.*))?")


def parse_symbols(text: str, where: str = "symbols.txt") -> list[Symbol]:
    symbols = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        m = _SYMBOL.fullmatch(line.strip())
        if not m:
            raise FormatError(f"{where}:{number}: cannot parse {line!r}")
        symbols.append(Symbol(m[1], m[2], int(m[3], 16), _options(m[4] or "", f"{where}:{number}")))
    return symbols


def _read(path: Path) -> str:
    try:
        return Path(path).read_text()
    except FileNotFoundError:
        raise FormatError(f"{relative(path)} does not exist: python tools/layout.py writes it") from None


def read_symbols(path: Path) -> list[Symbol]:
    return parse_symbols(_read(path), relative(path))


def format_symbols(symbols: list[Symbol]) -> str:
    return "".join(s.line() + "\n" for s in symbols)


# ------------------------------------------------------------------------------------------------------- splits.txt


@dataclass
class Range:
    """A unit's part of one section: [start, end), with options (align, rename, common, type ...)."""

    section: str
    start: int
    end: int
    options: list[tuple[str, str]] = field(default_factory=list)

    def option(self, key: str, default=None):
        return next((v for k, v in self.options if k == key), default)


@dataclass
class Unit:
    name: str
    ranges: list[Range] = field(default_factory=list)

    def range(self, section: str) -> Range | None:
        return next((r for r in self.ranges if r.section == section), None)


@dataclass
class Splits:
    sections: dict[str, list[tuple[str, str]]]
    units: list[Unit]

    def unit(self, name: str) -> Unit | None:
        return next((u for u in self.units if u.name == name), None)


def parse_splits(text: str, where: str = "splits.txt") -> Splits:
    sections: dict[str, list[tuple[str, str]]] = {}
    units: list[Unit] = []
    current: Unit | None = None
    in_sections = False
    for number, line in enumerate(text.splitlines(), 1):
        at = f"{where}:{number}"
        if not line.strip():
            continue
        if not line[0].isspace():
            if not line.endswith(":"):
                raise FormatError(f"{at}: expected 'Sections:' or a unit name ending in ':'")
            in_sections = line == "Sections:"
            current = None if in_sections else Unit(line[:-1])
            if current is not None:
                if any(u.name == current.name for u in units):
                    raise FormatError(f"{at}: unit {current.name} appears twice")
                units.append(current)
            continue
        fields = line.split(None, 1)
        options = _options(fields[1] if len(fields) > 1 else "", at)
        if in_sections:
            sections[fields[0]] = options
        elif current is None:
            raise FormatError(f"{at}: a range outside a unit")
        else:
            keys = dict(options)
            if "start" not in keys or "end" not in keys:
                raise FormatError(f"{at}: a range needs start: and end:")
            try:
                start, end = int(keys["start"], 16), int(keys["end"], 16)
            except ValueError:
                raise FormatError(f"{at}: start and end must be hexadecimal") from None
            if end < start:
                raise FormatError(f"{at}: end before start")
            current.ranges.append(
                Range(fields[0], start, end, [(k, v) for k, v in options if k not in ("start", "end")])
            )
    return Splits(sections, units)


def read_splits(path: Path) -> Splits:
    return parse_splits(_read(path), relative(path))


def format_splits(splits: Splits) -> str:
    lines = ["Sections:"]
    for name, options in splits.sections.items():
        lines.append(f"\t{name:<11} {_format_options(options)}".rstrip())
    for unit in splits.units:
        lines += ["", f"{unit.name}:"]
        for r in unit.ranges:
            options = [("start", f"0x{r.start:08X}"), ("end", f"0x{r.end:08X}"), *r.options]
            lines.append(f"\t{r.section:<11} {_format_options(options)}")
    return "\n".join(lines) + "\n"
